const errors = [];
const contextIsObject = $json.context && typeof $json.context === 'object' && !Array.isArray($json.context);

if ($json.route !== 'novel.create.intake') {
  errors.push('Invalid route: expected novel.create.intake.');
}
if ($json.target !== 'WF-002-P02') {
  errors.push('Invalid target: expected WF-002-P02.');
}
if ($json.status !== 'ready') {
  errors.push('Invalid status: expected ready.');
}
if ($json.is_valid === false) {
  errors.push('Intake was marked invalid.');
}
if (!contextIsObject) {
  errors.push('Invalid context: expected an object.');
}

const title = contextIsObject && typeof $json.context.novel_title === 'string'
  ? $json.context.novel_title.trim()
  : '';
if (!title) {
  errors.push('Novel title is required.');
}

return [{
  json: {
    ...$json,
    intake_valid: errors.length === 0,
    intake_errors: errors,
  },
}];

const context = $json.context && typeof $json.context === 'object' && !Array.isArray($json.context)
  ? $json.context
  : {};
const timestamp = new Date().toISOString();

return [{
  json: {
    ...$json,
    metadata_draft: {
      novel_id: 'NS-NOV-000001',
      title: typeof context.novel_title === 'string' ? context.novel_title.trim() : '',
      genre: typeof context.novel_genre === 'string' ? context.novel_genre.trim() : '',
      status: 'draft',
      created_at: timestamp,
      updated_at: timestamp,
      workflow_version: 'WF-002-P02-v1',
    },
  },
}];

const title = String($json.metadata_draft?.title ?? '');
const asciiSlug = title
  .normalize('NFKD')
  .replace(/[\u0300-\u036f]/g, '')
  .toLowerCase()
  .replace(/[^a-z0-9]+/g, '-')
  .replace(/^-+|-+$/g, '')
  .slice(0, 80)
  .replace(/-+$/g, '');
const fallbackSuffix = String($json.generated_uuid ?? '')
  .replace(/-/g, '')
  .slice(0, 8)
  .toLowerCase();

return [{
  json: {
    ...$json,
    generated_slug: asciiSlug || `novel-${fallbackSuffix}`,
  },
}];

return [{
  json: {
    ...$json,
    novel: {
      novel_id: $json.metadata_draft.novel_id,
      uuid: $json.generated_uuid,
      slug: $json.generated_slug,
      title: $json.metadata_draft.title,
      genre: $json.metadata_draft.genre,
      status: $json.metadata_draft.status,
      created_at: $json.metadata_draft.created_at,
      updated_at: $json.metadata_draft.updated_at,
      workflow_version: $json.metadata_draft.workflow_version,
    },
  },
}];
